// Canonical UART protocol. Companion copy is generated by sync-radio-modules.ps1.
#pragma once
#ifndef NUSA_DUPLEX_WIRE_H
#define NUSA_DUPLEX_WIRE_H
#include <stdint.h>
#include <stddef.h>
#include <string.h>

namespace NusaDuplexWire {
constexpr uint8_t VERSION = 3;
enum Type : uint8_t { MSG_CONFIG = 1, MSG_STATUS = 2, MSG_RX = 3, MSG_LISTEN = 4, MSG_TX = 5, MSG_CANCEL = 6 };
enum TxState : uint8_t { TX_IDLE = 0, TX_BUSY = 1, TX_DONE = 2, TX_FAILED = 3, TX_UNKNOWN = 4, TX_REJECTED = 5 };
constexpr size_t MAX_PAYLOAD = 272, MAX_BODY = MAX_PAYLOAD + 8;
constexpr size_t MAX_ENCODED = MAX_BODY + MAX_BODY / 254 + 2;
constexpr size_t CONFIG_SIZE = 14, STATUS_SIZE = 25;
inline void put16(uint8_t* p, uint16_t v) { p[0] = v >> 8; p[1] = v; }
inline uint16_t get16(const uint8_t* p) { return ((uint16_t)p[0] << 8) | p[1]; }
inline void put32(uint8_t* p, uint32_t v) {
  p[0] = v >> 24; p[1] = v >> 16; p[2] = v >> 8; p[3] = v;
}
inline uint32_t get32(const uint8_t* p) { return ((uint32_t)get16(p) << 16) | get16(p + 2); }
inline uint16_t crc16(const uint8_t* data, size_t len) {
  uint16_t crc = 0xffff;
  for (size_t i = 0; i < len; ++i) {
    crc ^= (uint16_t)data[i] << 8;
    for (uint8_t bit = 0; bit < 8; ++bit) crc = (crc & 0x8000) ? (crc << 1) ^ 0x1021 : crc << 1;
  }
  return crc;
}
struct Message { uint8_t type; uint16_t seq, len; uint8_t data[MAX_PAYLOAD]; };
struct Config {
  uint32_t freqKhz, bwHz;
  uint8_t sf, cr, sync;
  uint16_t preamble;
  int8_t power = 2;
};
inline void packConfig(uint8_t* out, const Config& c) {
  put32(out, c.freqKhz); put32(out + 4, c.bwHz);
  out[8] = c.sf; out[9] = c.cr; out[10] = c.sync; put16(out + 11, c.preamble);
  out[13] = (uint8_t)c.power;
}
inline bool unpackConfig(const uint8_t* data, size_t len, Config& c) {
  if (len != CONFIG_SIZE) return false;
  c = {get32(data), get32(data + 4), data[8], data[9], data[10], get16(data + 11), (int8_t)data[13]};
  return c.freqKhz >= 137000 && c.freqKhz <= 1020000 && c.bwHz >= 7800 &&
         c.bwHz <= 500000 && c.sf >= 7 && c.sf <= 12 && c.cr >= 5 && c.cr <= 8 && c.preamble >= 6 && c.power >= 2 && c.power <= 17;
}
// Returns a COBS-encoded frame including its terminating zero delimiter.
inline size_t encode(uint8_t type, uint16_t seq, const uint8_t* data, size_t len,
                     uint8_t* out, size_t capacity) {
  if (len > MAX_PAYLOAD || (len && !data) || capacity < MAX_ENCODED) return 0;
  uint8_t body[MAX_BODY];
  body[0] = VERSION; body[1] = type; put16(body + 2, seq); put16(body + 4, len);
  if (len) memcpy(body + 6, data, len);
  put16(body + 6 + len, crc16(body, 6 + len));
  size_t write = 1, codeAt = 0; uint8_t code = 1;
  for (size_t i = 0; i < len + 8; ++i) {
    if (!body[i]) { out[codeAt] = code; codeAt = write++; code = 1; }
    else {
      out[write++] = body[i];
      if (++code == 0xff) { out[codeAt] = code; codeAt = write++; code = 1; }
    }
  }
  out[codeAt] = code; out[write++] = 0;
  return write;
}
class Parser {
  uint8_t encoded[MAX_ENCODED]; size_t used = 0; bool overflow = false;
public:
  uint32_t errors = 0;
  void reset() { used = 0; overflow = false; }
  bool feed(uint8_t byte, Message& message) {
    if (byte) {
      if (used < sizeof(encoded)) encoded[used++] = byte; else overflow = true;
      return false;
    }
    if (!used && !overflow) return false;
    uint8_t body[MAX_BODY]; size_t read = 0, write = 0;
    bool good = !overflow;
    while (good && read < used) {
      uint8_t code = encoded[read++];
      if (!code || read + code - 1 > used) { good = false; break; }
      for (uint8_t i = 1; i < code; ++i) {
        if (write >= sizeof(body)) { good = false; break; }
        body[write++] = encoded[read++];
      }
      if (good && code != 0xff && read < used) {
        if (write >= sizeof(body)) { good = false; break; }
        body[write++] = 0;
      }
    }
    reset();
    if (!good || write < 8 || body[0] != VERSION || get16(body + 4) > MAX_PAYLOAD ||
        write != (size_t)get16(body + 4) + 8 || get16(body + write - 2) != crc16(body, write - 2)) {
      ++errors; return false;
    }
    message.type = body[1]; message.seq = get16(body + 2); message.len = get16(body + 4);
    if (message.len) memcpy(message.data, body + 6, message.len);
    return true;
  }
};
} // namespace NusaDuplexWire
#endif
